import json
import boto3
from typing import Dict, Any

def normalize_expense_fields(extracted_text: str) -> Dict[str, Any]:
    """
    Normalizes extracted expense fields into a standard JSON schema using AWS Textract.

    Args:
        extracted_text: Raw text extracted from an expense document.

    Returns:
        A dictionary with normalized expense fields following the schema:
        {
            "vendor": str,
            "date": str (ISO format),
            "amount": float,
            "currency": str,
            "category": str,
            "invoice_number": str
        }
    """
    # Initialize AWS Textract client
    textract = boto3.client('textract', region_name='us-east-1')

    # Prepare the document for Textract (assuming extracted_text is from an image/PDF)
    # In practice, you would upload the document to S3 and use its URI
    # For this example, we'll simulate the response structure
    response = textract.analyze_expense(
        Document={
            'Bytes': extracted_text.encode() if isinstance(extracted_text, str) else extracted_text
        }
    )

    # Initialize normalized fields
    normalized_fields = {
        "vendor": None,
        "date": None,
        "amount": None,
        "currency": None,
        "category": None,
        "invoice_number": None
    }

    # Process Textract response to extract and normalize fields
    for expense_doc in response['ExpenseDocuments']:
        for summary_field in expense_doc.get('SummaryFields', []):
            field_type = summary_field.get('Type', {}).get('Text')
            field_value = summary_field.get('ValueDetection', {}).get('Text')

            if not field_value:
                continue

            if field_type == 'VENDOR_NAME':
                normalized_fields['vendor'] = field_value
            elif field_type == 'INVOICE_RECEIPT_DATE':
                # Convert date to ISO format (assuming format like 'MM/DD/YYYY')
                try:
                    from datetime import datetime
                    date_obj = datetime.strptime(field_value, '%m/%d/%Y')
                    normalized_fields['date'] = date_obj.isoformat()
                except ValueError:
                    normalized_fields['date'] = field_value
            elif field_type == 'TOTAL':
                try:
                    normalized_fields['amount'] = float(field_value.replace(',', ''))
                except ValueError:
                    pass
            elif field_type == 'CURRENCY':
                normalized_fields['currency'] = field_value
            elif field_type == 'INVOICE_RECEIPT_ID':
                normalized_fields['invoice_number'] = field_value

        # Extract category from line items (simplified approach)
        for line_item in expense_doc.get('LineItemGroups', []):
            for item in line_item.get('LineItems', []):
                for field in item.get('LineItemExpenseFields', []):
                    if field.get('Type', {}).get('Text') == 'ITEM':
                        normalized_fields['category'] = field.get('ValueDetection', {}).get('Text')
                        break

    return normalized_fields
